    auto modinv = [](ll a, ll m) {
        ll m0 = m, y = 0, x = 1;
        if (m == 1) return 0LL;
        while (a > 1) {
            ll q = a / m;
            ll t = m;
            m = a % m, a = t;
            t = y;
            y = x - q * y;
            x = t;
